	{
		return true;
	}

	@ConfigItem(
		keyName = "npcChargeBarWidth",
		name = "Charge Width",
		description = "Width of the charge bar in pixels. 0 matches the NPC bar's width. "
			+ "Requires 'Charge Bar'.",
		section = TARGET_NPC_SECTION,
		position = 18
	)
	@Range(min = 0, max = 200)
