	// ==================== Player bar style (self + other players) ====================

	@ConfigItem(
		keyName = "showForSelf",
		name = "Show Bar",
		description = "Whether your own bar draws: never, only while you are in combat, or always.",
		section = PLAYER_SECTION,
		position = 0
	)
	default Visibility showForSelf()
	{
		return Visibility.TRACKED;
	}

	@ConfigItem(
