		HP("HP"),
		PRAYER("Prayer"),
		SPECIAL("Special"),
		RUN("Run Energy");

		private final String label;

		BarKind(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

}

