		@Override
		public boolean addEntity(Renderable renderable, boolean ui)
		{
			if (!ui)
			{
				return true;
			}
			if (renderable == client.getLocalPlayer())
			{
				return !suppressSelfOverheads;
			}
			return !overheadEligiblePlayers.contains(renderable);
		}
	};

