		SpriteID.StandardPoison160.FRONT, SpriteID.StandardPoison160.BACK,
	};

	/** Themed headbars that are still an actor's own hitpoints, just skinned per encounter. */
	private static final int[] THEMED_HEALTH = {
		SpriteID.HeadbarBlood120.FRONT, SpriteID.HeadbarBlood120.BACK,
		SpriteID.HeadbarIce120.FRONT, SpriteID.HeadbarIce120.BACK,
		SpriteID.HeadbarHeat120.FRONT, SpriteID.HeadbarHeat120.BACK,

		SpriteID.HeadbarBlood90.FRONT, SpriteID.HeadbarBlood90.BACK,
		SpriteID.HeadbarIce90.FRONT, SpriteID.HeadbarIce90.BACK,
		SpriteID.HeadbarHeat90.FRONT, SpriteID.HeadbarHeat90.BACK,

		SpriteID.HeadbarBlood30.FRONT, SpriteID.HeadbarBlood30.BACK,
	};

	/** The crashed star's own headbar. In scope because we draw a replacement for this one. */
	private static final int[] SHOOTING_STAR = {
		SpriteID.HeadbarShootingStar50.FRONT, SpriteID.HeadbarShootingStar50.BACK,
	};

	/** Headbars carrying a mechanic rather than hitpoints - a shield state, a timer. */
	private static final int[] INDICATOR_HEADBAR = {
		SpriteID.HeadbarShield100.COX_GREEN, SpriteID.HeadbarShield100.COX_BLUE,
		SpriteID.HeadbarOlmtimer100.YELLOW, SpriteID.HeadbarOlmtimer100.RED,
	};

	/**
	 * What hideNativeBar blanks: hitpoints only. ARMOUR/CHARGE and INDICATOR_HEADBAR are deliberately
	 * out - no replacement is drawn for those, so blanking one destroys information. SHIELD is out of
	 * this set too, but is blanked on its own while a shield window is open. See CLAUDE.md.
	 */
	static final int[] HEALTH_ONLY = concat(HEALTH, POISON, THEMED_HEALTH, SHOOTING_STAR);

	/** Every category combined; SHIELD omitted since PRAYER already includes it. Removal only. */
	static final int[] ALL = concat(
		HEALTH, ARMOUR, CHARGE, PRAYER, POISON, THEMED_HEALTH, INDICATOR_HEADBAR, SHOOTING_STAR);

	private static int[] concat(int[]... arrays)
	{
		int total = 0;
		for (int[] array : arrays)
		{
			total += array.length;
		}

		int[] result = new int[total];
		int pos = 0;
		for (int[] array : arrays)
		{
			System.arraycopy(array, 0, result, pos, array.length);
			pos += array.length;
		}
		return result;
	}

	private NativeHealthBarSprites()
	{
	}
}

package com.customhpbar;

import lombok.extern.slf4j.Slf4j;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;

/** Maps NPC IDs to max HP, from npc_hp.csv - by ID, since one name can span several HP values. */
@Slf4j
class NpcMaxHpTable
{
	private static final Map<Integer, Integer> TABLE = load();

	private static Map<Integer, Integer> load()
	{
		Map<Integer, Integer> table = new HashMap<>();
		try (InputStream in = NpcMaxHpTable.class.getResourceAsStream("npc_hp.csv"))
		{
			if (in == null)
			{
				log.warn("npc_hp.csv not found on classpath; NPC max HP lookups will be unavailable");
				return table;
			}

			try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				String line;
				while ((line = reader.readLine()) != null)
				{
					int comma = line.indexOf(',');
					if (comma < 0)
					{
						continue;
					}
					try
					{
						int id = Integer.parseInt(line.substring(0, comma).trim());
						int hp = Integer.parseInt(line.substring(comma + 1).trim());
						table.put(id, hp);
					}
					catch (NumberFormatException e)
					{
						log.debug("Skipping malformed npc_hp.csv line: {}", line);
					}
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to load npc_hp.csv; NPC max HP lookups will be unavailable", e);
		}
		return table;
	}

	/** Returns the known max HP for an NPC ID, or -1 if the ID is not in the table. */
	static int getMaxHp(int npcId)
	{
		Integer hp = TABLE.get(npcId);
		return hp != null ? hp : -1;
	}
}

package com.customhpbar;

import lombok.Value;
import lombok.extern.slf4j.Slf4j;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Maps NPC IDs to their elemental weakness, from npc_weakness.csv - keyed by ID since the same name
 * can carry different weaknesses across variants. Sourced from the OSRS Wiki's own infobox_monster
 * bucket, the same query its Elemental weakness page renders from. See CLAUDE.md.
 */
@Slf4j
class NpcWeaknessTable
{
	/** The four standard-spellbook elements. Only these exist in game - see CLAUDE.md. */
	enum Element
	{
		AIR, WATER, EARTH, FIRE
	}

	@Value
	static class Weakness
	{
		Element element;
		/** Extra magic damage and accuracy percent, 5-200. Not a fraction of anything - see CLAUDE.md. */
		int percent;
	}

	private static final Map<Integer, Weakness> TABLE = load();

	private static Map<Integer, Weakness> load()
	{
		Map<Integer, Weakness> table = new HashMap<>();
		try (InputStream in = NpcWeaknessTable.class.getResourceAsStream("npc_weakness.csv"))
		{
			if (in == null)
			{
				log.warn("npc_weakness.csv not found on classpath; NPC weakness lookups will be unavailable");
				return table;
			}

			try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				String line;
				while ((line = reader.readLine()) != null)
				{
					String[] parts = line.split(",");
					if (parts.length != 3)
					{
						continue;
					}
					try
					{
						int id = Integer.parseInt(parts[0].trim());
						Element element = Element.valueOf(parts[1].trim().toUpperCase(Locale.ROOT));
						table.put(id, new Weakness(element, Integer.parseInt(parts[2].trim())));
					}
					catch (IllegalArgumentException e)
					{
						log.debug("Skipping malformed npc_weakness.csv line: {}", line);
					}
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to load npc_weakness.csv; NPC weakness lookups will be unavailable", e);
		}
		return table;
	}

	/** The known elemental weakness for an NPC ID, or null if it has none. Most NPCs have none. */
	static Weakness getWeakness(int npcId)
	{
		return TABLE.get(npcId);
	}
}

